  ('Computer Science', 'OCR', 'gcse', '2.5', 'Languages and IDEs', 'What is assembly language?', 'A low-level language that uses mnemonics (e.g. ADD, LDA) to represent machine code instructions.', 6),
  ('Computer Science', 'OCR', 'gcse', '2.5', 'Languages and IDEs', 'What is a translator?', 'A program that converts source code into machine code.', 7),
  ('Computer Science', 'OCR', 'gcse', '2.5', 'Languages and IDEs', 'What is a compiler?', 'A translator that converts the whole program into machine code at once, producing an executable file.', 8),
  ('Computer Science', 'OCR', 'gcse', '2.5', 'Languages and IDEs', 'What is an interpreter?', 'A translator that converts and runs source code one line at a time.', 9),
  ('Computer Science', 'OCR', 'gcse', '2.5', 'Languages and IDEs', 'What is an assembler?', 'A translator that converts assembly language into machine code.', 10),
  ('Computer Science', 'OCR', 'gcse', '2.5', 'Languages and IDEs', 'Give an advantage of a compiler.', 'The compiled program runs faster and can be distributed without the source code.', 11),
  ('Computer Science', 'OCR', 'gcse', '2.5', 'Languages and IDEs', 'Give a disadvantage of a compiler.', 'Errors are reported only after the whole program is compiled, making debugging harder.', 12),
  ('Computer Science', 'OCR', 'gcse', '2.5', 'Languages and IDEs', 'Give an advantage of an interpreter.', 'Errors are found line by line, making debugging easier.', 13),
  ('Computer Science', 'OCR', 'gcse', '2.5', 'Languages and IDEs', 'Give a disadvantage of an interpreter.', 'The program runs more slowly and needs the interpreter every time it runs.', 14),
  ('Computer Science', 'OCR', 'gcse', '2.5', 'Languages and IDEs', 'What is an IDE?', 'An integrated development environment: software that provides tools for writing, testing and debugging code.', 15),
  ('Computer Science', 'OCR', 'gcse', '2.5', 'Languages and IDEs', 'What is an editor in an IDE?', 'A tool for writing and editing code, often with syntax highlighting and auto-completion.', 16),
  ('Computer Science', 'OCR', 'gcse', '2.5', 'Languages and IDEs', 'What is error diagnostics?', 'An IDE feature that identifies errors and suggests where they are.', 17),
  ('Computer Science', 'OCR', 'gcse', '2.5', 'Languages and IDEs', 'What is a run-time environment?', 'An IDE feature that allows a program to be run and tested within the IDE.', 18),
  ('Computer Science', 'OCR', 'gcse', '2.5', 'Languages and IDEs', 'What is a breakpoint?', 'A point where program execution pauses so the programmer can inspect variables.', 19),
  ('Computer Science', 'OCR', 'gcse', '2.5', 'Languages and IDEs', 'What is stepping through code?', 'Running a program one line at a time to see what happens.', 20),
  ('Computer Science', 'OCR', 'gcse', '2.5', 'Languages and IDEs', 'What is syntax highlighting?', 'Colouring different parts of code (keywords, variables, strings) to make it easier to read.', 21),
  ('Computer Science', 'OCR', 'gcse', '2.5', 'Languages and IDEs', 'What is auto-completion?', 'An IDE feature that suggests code as you type.', 22),
  ('Computer Science', 'OCR', 'gcse', '2.5', 'Languages and IDEs', 'What is auto-indentation?', 'An IDE feature that automatically indents code to show its structure.', 23),
  ('Computer Science', 'OCR', 'gcse', '2.5', 'Languages and IDEs', 'What is a translator''s role in an IDE?', 'It compiles or interprets code so it can be run.', 24),
  ('Computer Science', 'OCR', 'gcse', '2.5', 'Languages and IDEs', 'What is source code?', 'The code written by the programmer in a programming language.', 25),
  ('Computer Science', 'OCR', 'gcse', '2.5', 'Languages and IDEs', 'What is object code?', 'The machine code produced by a compiler.', 26),
  ('Computer Science', 'OCR', 'gcse', '2.5', 'Languages and IDEs', 'Why can''t computers understand high-level languages directly?', 'The CPU can only execute machine code (binary instructions).', 27),
  ('Computer Science', 'OCR', 'gcse', '2.5', 'Languages and IDEs', 'Why are programs written in high-level languages portable?', 'They can be translated for different types of processor.', 28),
  ('Computer Science', 'OCR', 'gcse', '2.5', 'Languages and IDEs', 'What is a mnemonic?', 'A short word representing a machine code instruction in assembly language, e.g. LDA for load.', 29),
  ('Computer Science', 'OCR', 'gcse', '2.5', 'Languages and IDEs', 'What is debugging?', 'Finding and fixing errors in a program.', 30)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Computer Science' AND exam_board = 'OCR' AND level = 'gcse'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;
